WITH Base AS (SELECT * FROM products WHERE stock_qty <= 368 AND supplier_id IN (14, 33)), Summary AS (SELECT CASE WHEN cost >= 640 THEN 'high' WHEN cost >= 320 THEN 'mid' ELSE 'low' END cost_bucket, COUNT(CASE WHEN category = 'Home' THEN 1 END) home_count FROM Base GROUP BY CASE WHEN cost >= 640 THEN 'high' WHEN cost >= 320 THEN 'mid' ELSE 'low' END) SELECT cost_bucket, home_count FROM Summary ORDER BY home_count DESC, cost_bucket ASC LIMIT 5
